VALUES ('f_8eb8c04713ff6a6ef4a265', 'Phone message checks', 'application/vnd.google-apps.spreadsheet', '["d_65c76e0b87aa7e9b84d1df"]', 'vincent.parker@harmonygames.co', '["samuel.turner@harmonygames.co", "oliver.brooks@harmonygames.co", "owen.baker@harmonygames.co", "leonard.hayes@harmonygames.co"]', '[{"email": "samuel.turner@harmonygames.co", "role": "reader"}, {"email": "oliver.brooks@harmonygames.co", "role": "reader"}, {"email": "owen.baker@harmonygames.co", "role": "reader"}, {"email": "leonard.hayes@harmonygames.co", "role": "reader"}]', 'private', '["vincent.parker@harmonygames.co"]', '2025-09-24T15:00:05Z', '2025-09-15T12:51:17Z', false, false);
