INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_dc45e0e5a8b8635c1b82b2', 'Beta message rule', 'leonard.hayes@harmonygames.co', '["samuel.turner@harmonygames.co", "vincent.parker@harmonygames.co", "robert@harmonygames.co", "arthur.blake@harmonygames.co"]', 'private', E'Beta message rule\nA message is anything the game puts on a player''s phone while the game is closed.\nRun these tests in order and stop at the first one that fails.\n1. The feature behind it is in the beta.\n2. The client can send it without a server.\n3. The client already schedules it.\n4. It can reach the players it is written for. A player only counts once our own permission ask has happened, the settings toggle doesn''t count. It fails only if none of them count.\n5. It fires on the right day. The hour doesn''t matter for beta, the day does.\n6. Vincent has seen it arrive on both iOS and Android.\nGo: it passes all six. Drop: it fails test 1, or the client already covers it under another message, then name that message. Hold: anything else, and name the test it failed.\nIn the beta means live in Zombie Match today or on the BETA list of the ZM ROADMAP board.\nNeither status column on the sheet decides anything.\nWhat Vincent counts as seen is in his QA note. The permission ask is Robert''s call.\nThe final headline is the latest line I''ve called. A line that differs from what the client ships needs a string ticket under DES-314, because the strings are hard-coded, so open one when you make the call. Emoji don''t count as a different line. Final headline and String change are only for Go rows. Audience is who the ask says it''s for.\nDrop tickets go to Canceled, Go tickets stay as they are, Hold tickets go back to Todo unless the roadmap says otherwise.', '[{"start": 0, "end": 18, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 18, "end": 1462, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', '740e0d0bac', 'f_dc45e0e5a8b8635c1b82b2', '2025-09-26T17:10:54Z', '2025-09-26T17:10:54Z');
