VALUES ('394f73aa43aa303a755bc81b2cf43840', '1758909739.853209', 'C0880U9751A', 'message', 'EMPLOYEE_0026_SLACK_ID', 'honestly just send all the Ready ones at beta and fix copy after, the readiness deck says 6 anyway', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-26T18:02:19.853209Z', '{}');
