VALUES ('37c5701a1780374401d295e86884f276', '1759167608.326578', 'C0880U9751A', 'message', 'EMPLOYEE_0016_SLACK_ID', 'Permission ask for beta: leaving our own ask after level 20, not pushing it further, Leonard''s right that we need PNs for retention. The Unity popup at launch on iOS stays as it is.', NULL, '1759167608.326578', 1, 1, '1759170096.924778', false, NULL, '[]', '[]', '[]', '2025-09-29T17:40:08.326578Z', '{}');
