VALUES ('09aae609aa744fb23288c7dcbac9926c', '1759170096.924778', 'C0880U9751A', 'message', 'EMPLOYEE_0025_SLACK_ID', 'that popup doesn''t switch anything on btw. NotificationManager only schedules once our own ask has run or they switch it on from settings, on both platforms', '37c5701a1780374401d295e86884f276', '1759167608.326578', 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-29T18:21:36.924778Z', '{}');
