VALUES ('d2b16907dc8c10fe5052805751097b58', '1759169129.445834', 'C08R8CHB0QL', 'message', 'EMPLOYEE_0038_SLACK_ID', 'random one while I''m here: the ''taken over'' push reads like we''ve given up. make it "Your Squad Needs You Back", body stays.', 'a3e78e820b9f880ef4e3d941562110df', '1759159849.386619', 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-29T18:05:29.445834Z', '{}');
