VALUES ('4a5ee02518ff2fbeacaef2fc6d5a9ef9', '1759174846.723833', 'D06UFE81RF0', 'message', 'EMPLOYEE_0012_SLACK_ID', 'also on the race one I passed: that iPhone was still on the 5-minute timers build when I ticked it, so scratch iOS. put the real 0.3.40 on it after and it never showed up. Android is fine.', 'c42902df5f54c75c1a6e3529cd25121c', '1759163970.141449', 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-29T19:40:46.723833Z', '{}');
