INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json)
VALUES ('363d61ffd3daeb6972a01cdb92db9520', '1759245146.720608', 'C0880U9751A', 'message', 'EMPLOYEE_0012_SLACK_ID', 'on 0.3.49 the Full Ammo one didn''t show up after a full refill, tried it twice on the iPhone this morning. the lapsed ones are still coming through. taking my tick off Full Ammo until I''ve seen it land', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-30T15:12:26.720608Z', '{}');
INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json)
VALUES ('6fd96f3c3977cee8345e685d31cbc177', '1759264851.763895', 'D06L58XCVKK', 'message', 'EMPLOYEE_0038_SLACK_ID', 'Samuel, we''re about to put more money behind beta and D1 and D7 are what we get judged on, so I want one straight answer on what we actually say to players. The PN sheet says six are Ready and I don''t trust that. Take every row on the PNs Beta tab plus every ask for a new phone message that''s been filed on a ticket or a card up to today, and make a call on each one using the message rule doc. Put it in one sheet in your Drive folder, one row per message: Message, Ticket, Call, What''s missing, Audience, Final headline, String change. Next to it a one-page note for the team: start with D1 and D7 for the Sep 15 cohort week from the warehouse, iOS and Android separately, then the lapsed reminders the client schedules day by day, and anything the client already schedules that''s still a Hold and why. I made tickets for the sheet rows under DES-314 and people added their asks there. Leave the call as a comment on each ticket and move the ticket to match. Anything with no ticket gets one, but don''t make a second one for something that already has a ticket under whatever name. Every Go goes on a checklist on our push notifications card so Vincent can tick it off. Email each person who asked for something, apart from me, to say what happened to their asks. When it''s done tell me here how many Go, Hold and Drop.', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-30T20:40:51.763895Z', '{}');
