VALUES ('vincent.parker@harmonygames.co/<CAYr96MXDLI990PHRTvHgBNzJ5rcdWTpWyXj8JCA@mail.gmail.com>', 'vincent.parker@harmonygames.co/1843335316636098078', 'vincent.parker@harmonygames.co', '["SENT"]', 'Hi all, How I''m checking the phone messages for beta. Seen only counts on a store build, on a real iOS device and a real Android device. A b', 1757941548000, '2025-09-15T13:05:48Z', 1229, 'Phone messages for beta', 'vincent.parker@harmonygames.co', 'Vincent Parker', '["Samuel Turner <samuel.turner@harmonygames.co>", "Oliver Brooks <oliver.brooks@harmonygames.co>", "Owen Baker <owen.baker@harmonygames.co>"]', '[]', '[]', '[]', E'Hi all,\r\n\r\nHow I''m checking the phone messages for beta. Seen only counts on a store build, on a real iOS device and a real Android device. A build with shortened timers doesn''t count, it only proves the code path. Moving the phone date forward on a store build is fine.\r\n\r\nPasses go in the Phone message checks sheet.\r\n\r\nVincent', NULL, '[{"name": "Message-ID", "value": "<CAYr96MXDLI990PHRTvHgBNzJ5rcdWTpWyXj8JCA@mail.gmail.com>"}, {"name": "Date", "value": "Mon, 15 Sep 2025 13:05:48 +0000"}, {"name": "Subject", "value": "Phone messages for beta"}, {"name": "From", "value": "Vincent Parker <vincent.parker@harmonygames.co>"}, {"name": "To", "value": "Samuel Turner <samuel.turner@harmonygames.co>, Oliver Brooks <oliver.brooks@harmonygames.co>, Owen Baker <owen.baker@harmonygames.co>"}]', NULL, NULL, NULL, '[]');
