VALUES ('samuel.turner@harmonygames.co/<[SOURCE_ORG_0001]-Games/match3d/pull/248/review/2963610417@github.com>', 'samuel.turner@harmonygames.co/1836006988541924555', 'samuel.turner@harmonygames.co', '["INBOX", "IMPORTANT", "Label_b19fb8d1b3", "CATEGORY_PERSONAL"]', '@arthur.blake commented on this pull request. > + DateTime fireTime = referenceDate.AddDays(i * 7); This counts seven days from the day they', 1750971494000, '2025-06-26T20:58:14Z', 3585, 'Re: [[SOURCE_ORG_0001]-Games/match3d] Push notification (PR #248)', 'SVC_0248_EMAIL', 'SVC_0248_NAME', '["SVC_3649_NAME <SVC_3649_EMAIL>"]', '["Samuel Turner <samuel.turner@harmonygames.co>", "SVC_0613_NAME <SVC_0613_EMAIL>"]', '[]', '["SVC_5111_NAME <SVC_5111_EMAIL_PLUS_ALIAS_2595>"]', E'@arthur.blake commented on this pull request.\r\n\r\n> +                DateTime fireTime = referenceDate.AddDays(i * 7);\r\n\r\nThis counts seven days from the day they last left the game, so it isn''t tied to the rollover. Fine to merge, but it isn''t a reset message until it''s anchored to the real reset.\r\n\r\n-- \r\nReply to this email directly or view it on github:\r\nhttps://github.com/[SOURCE_ORG_0001]-Games/match3d/pull/248#discussion_r2169904417\r\nYou are receiving this because you authored the thread.\r\n\r\nMessage ID: <[SOURCE_ORG_0001]-Games/match3d/pull/248/review/2963610417@github.com>', NULL, '[{"name": "Message-ID", "value": "<[SOURCE_ORG_0001]-Games/match3d/pull/248/review/2963610417@github.com>"}, {"name": "Date", "value": "Thu, 26 Jun 2025 20:58:14 +0000"}, {"name": "Subject", "value": "Re: [[SOURCE_ORG_0001]-Games/match3d] Push notification (PR #248)"}, {"name": "From", "value": "SVC_0248_NAME <SVC_0248_EMAIL>"}, {"name": "To", "value": "SVC_3649_NAME <SVC_3649_EMAIL>"}, {"name": "In-Reply-To", "value": "<[SOURCE_ORG_0001]-Games/match3d/pull/248@github.com>"}, {"name": "References", "value": "<[SOURCE_ORG_0001]-Games/match3d/pull/248@github.com>"}]', NULL, NULL, NULL, '[]');
