INSERT INTO github.github_review_comments (id, pr_id, author_login, body, path, diff_hunk, line, position, commit_id, in_reply_to_id, created_at, seq)
VALUES ('harmonygames-Games/match3d#248#rc_18', 'harmonygames-Games/match3d#248', 'EMPLOYEE_0025_GITHUB_USERNAME', 'This counts seven days from the day they last left the game, so it isn''t tied to the rollover. Fine to merge, but it isn''t a reset message until it''s anchored to the real reset.', 'Assets/Scripts/Notifications/NotificationManager.cs', E'@@ -0,0 +1,537 @@\n+﻿using System;\n+using System.Collections;\n+using UnityEngine;\n+using HarmonyLogging;\n+using Match3D.Utility;\n+using Match3D.Game.Levels;\n+\n+#if UNITY_ANDROID\n+using Unity.Notifications.Android;\n+using UnityEngine.Android;\n+#elif UNITY_IOS\n+using Unity.Notifications.iOS;\n+#endif\n+\n+public class NotificationManager : MonoBehaviour\n+{\n+    public static NotificationManager Instance { get; private set; }\n+    public bool NotificationsEnabled { get; private set; } = false; // Default to false\n+    private const string AndroidChannelId = "default_channel";\n+    private const string NotificationsEnabledKey = "NotificationsEnabled";\n+    public const string NotificationsPermission = "NotificationsPermission";\n+    public const string FirstNotificationsPermission = "FirstNotificationsPermission";\n+    private const string PermissionGranted = "PermissionGranted";\n+    private const string PermissionDenied = "PermissionDenied";\n+\n+    private void Awake()\n+    {\n+        if (Instance == null)\n+        {\n+            Instance = this;\n+            DontDestroyOnLoad(gameObject);\n+            // Load the notificationsEnabled flag from PlayerPrefs\n+            NotificationsEnabled = PlayerPrefs.GetInt(NotificationsEnabledKey, 0) == 1;\n+        }\n+        else\n+        {\n+            Destroy(gameObject);\n+        }\n+    }\n+\n+    private void Start()\n+    {\n+        Init();\n+    }\n+\n+    void OnEnable()\n+    {\n+#if UNITY_ANDROID\n+        AndroidNotificationCenter.OnNotificationReceived += OnNotificationReceived;\n+#elif UNITY_IOS\n+        iOSNotificationCenter.OnNotificationReceived += OnNotificationReceived;\n+#endif\n+    }\n+\n+    void OnDisable()\n+    {\n+#if UNITY_ANDROID\n+        AndroidNotificationCenter.OnNotificationReceived -= OnNotificationReceived;\n+#elif UNITY_IOS\n+        iOSNotificationCenter.OnNotificationReceived -= OnNotificationReceived;\n+#endif\n+    }\n+\n+#if UNITY_ANDROID\n+    private void OnNotificationReceived(AndroidNotificationIntentData data)\n+    {\n+    }\n+#endif\n+\n+#if UNITY_IOS\n+    private void OnNotificationReceived(iOSNotification notification)\n+    {\n+    }\n+#endif\n+\n+    public void Init()\n+    {\n+        // Only initialize notifications if the user hasn''t made a choice yet\n+        InitializeNotifications();\n+    }\n+\n+    private void OnApplicationFocus(bool focus)\n+    {\n+        if (focus)\n+        {\n+            // Check and update notification permission status\n+#if UNITY_ANDROID\n+            if (Permission.HasUserAuthorizedPermission("android.permission.POST_NOTIFICATIONS"))\n+            {\n+                PlayerPrefs.SetString(NotificationsPermission, PermissionGranted);\n+            }\n+            else\n+            {\n+                PlayerPrefs.SetString(NotificationsPermission, PermissionDenied);\n+            }\n+#elif UNITY_IOS\n+            var notificationSettings = iOSNotificationCenter.GetNotificationSettings();\n+            if (notificationSettings.AuthorizationStatus == AuthorizationStatus.Authorized)\n+            {\n+                PlayerPrefs.SetString(NotificationsPermission, PermissionGranted);\n+            }\n+            else\n+            {\n+                PlayerPrefs.SetString(NotificationsPermission, PermissionDenied);\n+            }\n+#endif\n+            // Clear notifications and check for any triggered by app focus\n+            ClearNotifications();\n+            CheckIfAppOpenedFromNotification();\n+        }\n+        else\n+        {\n+            ClearNotifications();\n+            ScheduleDominoNotifications();\n+        }\n+    }\n+\n+    public void EnableNotifications()\n+    {\n+        NotificationsEnabled = true;\n+        PlayerPrefs.SetInt(NotificationsEnabledKey, 1);\n+        PlayerPrefs.Save();\n+\n+        ClearNotifications();\n+        ScheduleDominoNotifications();\n+    }\n+\n+    public void DisableNotifications()\n+    {\n+        NotificationsEnabled = false;\n+        PlayerPrefs.SetInt(NotificationsEnabledKey, 0);\n+        PlayerPrefs.Save();\n+        ClearNotifications();\n+    }\n+\n+    private void ScheduleDominoNotifications()\n+    {\n+        if (!NotificationsEnabled /*|| PlayerData.Profile == null*/)\n+            return;\n+\n+        DateTime serverToday = HarmonyTime.GetServerDateTime().Date;\n+\n+        // Lives recharge\n+        string LivesRechargedTitle = "Full Ammo Reloaded! 🔫";\n+        string LivesRechargedMessage = "Your energy is fully charged! The zombies are closing in—jump back into the battle now and show them who''s boss. 🧟⚔️";\n+\n+        // Lapsed last session reminder\n+        string OneDayLapsedTitle = "The Horde Is Growing… 🧟‍♂️";\n+        string OneDayLapsedMessage = "The zombie outbreak won’t stop on its own! Return to Puzzles vs Zombies now and continue your mission. New challenges await! 🧠🔥";\n+\n+        // Lapsed Weekly reminder batch\n+        string WeeklyReminderTitle = "They’ve Taken Over… Can You Stop Them? 😱";\n+        string WeeklyReminderMessage = "It’s been a while, survivor. The undead are stronger than ever. Rally your gear and get back into the fray before it’s too late! 🧟‍♀️💥";\n+\n+        // Lapsed Weekly reminder batch\n+        string WeeklyLeaderboardTitle = "Weekly Rankings Reset! 🎯";\n+        string WeeklyLeaderboardMessage = "New week, fresh shot at glory! Climb the leaderboard and prove you’re the ultimate zombie slayer. Ready to dominate? 🏙️🧟";\n+\n+        // Finish first tutorial\n+        string FinishFirstTutorialTitle = "Finish Your First Mission! 🧟‍♀️📈";\n+        string FinishFirstTutoriaMessage = "You’re so close! Complete your first mission in Puzzles vs Zombies and unlock powerful tools to fight the undead. The city needs you! 💪";\n+\n+        // Plague Race Event\n+        string PlagueRaceTitle = "Plague Race Is On! 🌊🚣";\n+        string PlagueRaceMessage = "Compete in Plague Race now! Speed through levels, outmatch rivals, and claim your place on the leaderboard before time runs out. ⚡🏆";\n+\n+        // Schedule lives regen notification\n+        ScheduleLivesRechargedNotification(LivesRechargedTitle, LivesRechargedMessage, serverToday);\n+\n+        // Schedule Finish first tutorial\n+        ScheduleFinishFirstTutorialNotification(FinishFirstTutorialTitle, FinishFirstTutoriaMessage, serverToday);\n+\n+        // Schedule Lapsed last session reminder\n+        DailyNotifications(OneDayLapsedTitle, OneDayLapsedMessage, serverToday);\n+\n+        // Schedule Weekly reminder batch\n+        BatchScheduleWeeklyNotifications(WeeklyReminderTitle, WeeklyReminderMessage, 4, serverToday);\n+\n+        // Schedule Weekly Leaderboard reminder batch\n+        BatchScheduleWeeklyLeaderboardNotifications(WeeklyLeaderboardTitle, WeeklyLeaderboardMessage, 4, serverToday);\n+\n+        // Schedule Events\n+        BatchSchedulePlagueRace(PlagueRaceTitle, PlagueRaceMessage, 5, serverToday);\n+    }\n+\n+    private void ScheduleLivesRechargedNotification(string title, string message, DateTime serverToday)\n+    {\n+        if (LivesManager.IsInfiniteLivesActive)\n+        {\n+            return;\n+        }\n+\n+        if (LivesManager.Instance != null && LivesManager.Instance.Lives < LivesManager.MaxLives)\n+        {\n+            var livesToRecharge = LivesManager.MaxLives - LivesManager.Instance.Lives;\n+            var lastRewardTime = LivesManager.Instance.GetRegenerationTime();\n+            TimeSpan timeSinceLastReward = DateTime.UtcNow - lastRewardTime;\n+            float nextLifeTimeRemaining = (float)LivesManager.RegenTime.TotalSeconds - (float)timeSinceLastReward.TotalSeconds;\n+            float allLivesTimeRemaining = nextLifeTimeRemaining + (livesToRecharge - 1) * (float)LivesManager.RegenTime.TotalSeconds;\n+            if (allLivesTimeRemaining > 0)\n+            { \n+                ScheduleNotification(title, message, DateTime.Now.AddSeconds(allLivesTimeRemaining));\n+            }\n+        }\n+    }\n+\n+    private void ScheduleFinishFirstTutorialNotification(string title, string message, DateTime serverToday)\n+    {\n+        if (LevelManager.Instance != null && LevelManager.Instance.GetCurrentLevelNumber() < ZombieConstants.FirstTutorialFinished)\n+        {\n+            DateTime date = serverToday.AddHours(12);\n+            ScheduleNotification(title, message, date);\n+        }\n+    }\n+\n+    private void DailyNotifications(string title, string message, DateTime serverToday)\n+    {\n+        DateTime date = serverToday.AddDays(1);\n+        ScheduleNotification(title, message, date);\n+    }\n+\n+    private void BatchScheduleWeeklyNotifications(string title, string message, int weeksToCover, DateTime referenceDate)\n+    {\n+        for (int i = 1; i <= weeksToCover; i++)\n+        {\n+            DateTime fireTime = referenceDate.AddDays(i * 7);\n+            ScheduleNotification(title, message, fireTime);\n+        }\n+    }\n+\n+    private void BatchSchedulePlagueRace(string title, string message, int daysToCover, DateTime serverToday)\n+    {\n+        if (LevelManager.Instance != null && LevelManager.Instance.GetCurrentLevelNumber() >= ZombieConstants.PlagueRaceUnlockLevel)\n+        {\n+            for (int i = 1; i <= daysToCover; i++)\n+            {\n+                DateTime date = serverToday.AddDays(i);\n+                DateTime fireTime = date.AddMinutes(15);\n+                ScheduleNotification(title, message, fireTime);\n+            }\n+        }\n+    }\n+\n+    private void BatchScheduleWeeklyLeaderboardNotifications(string title, string message, int weeksToCover, DateTime referenceDate)\n+    {\n+        if (LevelManager.Instance != null && LevelManager.Instance.GetCurrentLevelNumber() >= ZombieConstants.LeaderboardsUnlockLevel)\n+        {\n+            for (int i = 1; i <= weeksToCover; i++)\n+            {\n+                DateTime fireTime = referenceDate.AddDays(i * 7);', NULL, NULL, NULL, NULL, '2025-06-26T20:58:14Z', 18);
