INSERT INTO linear.linear_comments (id, issue_id, author_id, parent_id, body, is_edited, created_at, updated_at, sequence)
VALUES ('cmt_e2e2926a2080ca53c4ea', 'ZOM-483', 'usr_49b9dfa5208d400d', NULL, 'we do hand out infinite lives, just not on the first session. could we also remind players on their phone when their infinite lives are about to run out? not the lives recharged one, this is for players with infinite lives running. local timer per Arthur.', false, '2025-09-26T16:41:28Z', '2025-09-26T16:41:28Z', 1);
INSERT INTO linear.linear_comments (id, issue_id, author_id, parent_id, body, is_edited, created_at, updated_at, sequence)
VALUES ('cmt_f1b8a109dfa70cdc4565', 'ZOM-542', 'usr_fc22d5941b2aeb5c', NULL, 'while someone''s in here, can we get a phone reminder once the daily Boss Arena attempts refill? separate from the weekly board ping Robert filed, this is for players who used their attempts. Arthur says a local timer is enough.', false, '2025-09-26T13:27:41Z', '2025-09-26T13:27:41Z', 1);
INSERT INTO linear.linear_comments (id, issue_id, author_id, parent_id, body, is_edited, created_at, updated_at, sequence)
VALUES ('cmt_2b519285937e7fa79453', 'ZOM-556', 'usr_8140f09bf9f1b94c', NULL, 'the gift streak itself is live, this only breaks the skip case. could we also send a phone reminder the evening before the daily gift streak resets? separate from the chest ping Calvin filed, this is for players on a gift streak. local timer per Arthur.', false, '2025-09-26T14:08:12Z', '2025-09-26T14:08:12Z', 1);
